import{_ as r,C as a,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Lead analysis","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/reporting/lead-analysis.md","filePath":"master/sales/crm/reporting/lead-analysis.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/reporting/lead-analysis.md"};function g(h,e,d,p,u,c){const o=a("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="lead-analysis" tabindex="-1">Lead analysis <a class="header-anchor" href="#lead-analysis" aria-label="Permalink to &quot;Lead analysis&quot;">​</a></h1><p>Lead analysis covers every lead and every opportunity, including the ones you lost. You use it to count how many records came in, see who works on them, and compare won and lost results over time.</p><blockquote><p><strong>In simple words:</strong> Pipeline analysis looks at open deals. Lead analysis looks at everything, from the first lead to the final win or loss.</p></blockquote><p>Open <code>CRM → Reporting → Leads</code>. The page title is <strong>Leads Analysis</strong>.</p><h2 id="the-report-page" tabindex="-1">The report page <a class="header-anchor" href="#the-report-page" aria-label="Permalink to &quot;The report page&quot;">​</a></h2>',5)),s(o,{src:"/images1/crm/lead-analysis-list.png",alt:"Leads analysis list on the Leads tab with Group by, Measure and the summary rows"}),e[1]||(e[1]=t('<p>The page has two views: <strong>List</strong> and <strong>Graph</strong>.</p><h3 id="views-tabs" tabindex="-1">Views (tabs) <a class="header-anchor" href="#views-tabs" aria-label="Permalink to &quot;Views (tabs)&quot;">​</a></h3><ul><li><strong><em>Leads:</em></strong> Records that are still leads. This tab opens first.</li><li><strong><em>Opportunities:</em></strong> Records that are opportunities.</li><li><strong><em>Mine:</em></strong> Records where you are the salesperson.</li><li><strong><em>Won:</em></strong> Records in a won stage.</li><li><strong><em>Lost:</em></strong> Records you marked as lost.</li></ul><p>The <strong>Default</strong> tab shows every record.</p><p><strong>Example:</strong> The dev data shows 24 records in <strong>Default</strong>, 16 in <strong>Leads</strong>, 8 in <strong>Opportunities</strong>, 12 in <strong>Mine</strong>, 1 in <strong>Won</strong> and 0 in <strong>Lost</strong>.</p><h3 id="default-filter" tabindex="-1">Default filter <a class="header-anchor" href="#default-filter" aria-label="Permalink to &quot;Default filter&quot;">​</a></h3><p>The report starts with the rule <strong>Created On is after</strong> the first day of this year. Edit or remove it to look further back.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p><strong>Name</strong>, <strong>Type</strong>, <strong>Customer</strong>, <strong>Stage</strong>, <strong>Expected Revenue</strong>, <strong>Probability</strong>, <strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Expected Closing</strong>, <strong>Created On</strong> and <strong>Closed On</strong>. Use the column toggle to add <strong>Lost Reason</strong>, <strong>Country</strong> and <strong>City</strong>. The last column shows the measure.</p><p>A summary row shows the total for the page. A second row shows the total for the whole report.</p><h3 id="search-filter-group-and-export" tabindex="-1">Search, filter, group and export <a class="header-anchor" href="#search-filter-group-and-export" aria-label="Permalink to &quot;Search, filter, group and export&quot;">​</a></h3><ul><li>Type in the search box to find a record.</li><li>Use the <strong>Salespeople</strong> and <strong>Sales Teams</strong> filters.</li><li>Use the filter builder for rules on <strong>Salesperson</strong>, <strong>Type</strong>, <strong>Expected Closing</strong>, <strong>Active</strong>, <strong>Won</strong> and <strong>Closed Date</strong>.</li><li>Click a row to open the lead or opportunity. Lost rows do not open.</li><li>Select rows to export, delete, restore, mark as lost, merge, or send email or SMS.</li></ul><h2 id="group-by" tabindex="-1">Group by <a class="header-anchor" href="#group-by" aria-label="Permalink to &quot;Group by&quot;">​</a></h2><p>The options are:</p><ul><li><strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Stage</strong>, <strong>Type</strong></li><li><strong>City</strong>, <strong>Country</strong>, <strong>Company</strong></li><li><strong>Lost Reason</strong></li><li><strong>Campaign</strong>, <strong>Medium</strong>, <strong>Source</strong></li><li><strong>Expected Closing</strong>, <strong>Creation Date</strong>, <strong>Conversion Date</strong>, <strong>Closed Date</strong> (grouped by month)</li></ul><p><strong>Type</strong> is the only option that this report has and Pipeline analysis does not. It separates leads from opportunities.</p><h2 id="measure" tabindex="-1">Measure <a class="header-anchor" href="#measure" aria-label="Permalink to &quot;Measure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Measure</th><th>True meaning</th></tr></thead><tbody><tr><td><strong>Count</strong></td><td>How many records are in the group. This is the default.</td></tr><tr><td><strong>Expected Revenue</strong></td><td>The sum of <strong>Expected Revenue</strong>. Leads often have 0.</td></tr><tr><td><strong>Prorated Revenue</strong></td><td>The sum of expected revenue times probability divided by 100.</td></tr><tr><td><strong>Probability (avg.)</strong></td><td>The average <strong>Probability</strong>, shown as a percentage.</td></tr><tr><td><strong>Days to Assign</strong></td><td>The average days from creation to the day a salesperson was assigned.</td></tr><tr><td><strong>Days to Close</strong></td><td>The average days from creation to the closed date.</td></tr></tbody></table><h2 id="the-graph-view" tabindex="-1">The Graph view <a class="header-anchor" href="#the-graph-view" aria-label="Permalink to &quot;The Graph view&quot;">​</a></h2>',19)),s(o,{src:"/images1/crm/lead-analysis-graph.png",alt:"Leads analysis graph showing Count by Creation Date, split by Sales Team"}),e[2]||(e[2]=t('<ol><li>Click <strong>Graph</strong> in the view switch.</li><li>Choose a <strong>Measure</strong>. The default is <strong>Count</strong>.</li><li>Choose <strong>Group by</strong>. The default is <strong>Creation Date</strong>, so each bar is one month.</li><li>Choose <strong>Split by</strong>. The default is <strong>Sales Team</strong>, so each bar is stacked by team.</li></ol><p>The title reads, for example, <strong>Count by Creation Date</strong>.</p><h2 id="read-the-report" tabindex="-1">Read the report <a class="header-anchor" href="#read-the-report" aria-label="Permalink to &quot;Read the report&quot;">​</a></h2><p><strong>Example:</strong> On the <strong>Leads</strong> tab with the year filter, the summary row shows <strong>Count 16</strong> and <strong>Expected Revenue $0.00</strong>.</p><ol><li>Set <strong>Group by</strong> to <strong>Salesperson</strong>. Each group shows how many leads each person holds.</li><li>Change <strong>Measure</strong> to <strong>Probability (avg.)</strong>. You see which salesperson holds the more promising leads.</li><li>Switch to the <strong>Won</strong> tab and group by <strong>Source</strong>. You see which source brings the deals you win.</li><li>Switch to the <strong>Lost</strong> tab and group by <strong>Lost Reason</strong>. You see why you lose.</li></ol><p>The leads here have 0 expected revenue. That is normal, because revenue is usually added after conversion.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>The report reads the same records as the <strong>Leads</strong> and <strong>My Pipeline</strong> menus, plus lost ones.</li><li>A lost record is one that you marked as lost. It is archived, shown in the <strong>Lost</strong> tab, and has the stage label <strong>Lost</strong>.</li><li>A lead keeps its history after conversion. <strong>Conversion Date</strong> records when it became an opportunity.</li><li>Nothing you change on this page edits a record, except the bulk actions you start on purpose.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./pipeline-analysis.html">Pipeline analysis</a></li><li><a href="./../configuration/lost-reasons.html">Lost reasons</a></li><li><a href="./../pipeline/mark-won-lost.html">Mark won or lost</a></li><li><a href="./">Reporting overview</a></li></ul>',10))])}const b=r(l,[["render",g]]);export{y as __pageData,b as default};
